// 1. Class defining the Template Member Function
class Distribution {
public:
    // Template member function definition (delayed instantiation)
    template <class URNG>
    int sample(URNG& g) const {
        return g() % 100;
    }
};

// 2. Concrete Type used for Instantiation
class PRNG_Mock {
public:
    int operator()() { return 95; }
};

Distribution dist;
PRNG_Mock engine;

// Instantiation Point 1: compiler generates Distribution::sample<PRNG_Mock>
int val = dist.sample(engine);
// val is now 95 % 100 = 95
